mapper.select:
select o.goods_title as goodsTitle, o.goods_price as goodsPrice, o.quantity, o.total_amount as totalAmount, o.order_status as orderStatus, o.create_time as createTime, o.create_date as createDate, o.refund_time as refundTime, o.refund_date as refundDate, o.order_id as orderId, c.photo_url as photoUrl, c.customer_name as customerName, c.gender, c.phone, c.register_time as registerTime, o.out_trade_no as outTradeNo, o.transaction_id as transactionId, o.out_refund_no as outRefundNo, o.snapshot_id as snapshotId, count(a.order_id) as num from med_exam_package p inner join trade_order o on p.id = o.goods_id inner join crm_customer c on c.id = o.customer_id left join med_exam_appointment a on a.order_id = o.order_id
p.package_code like concat('%',#{dto.packageCode},'%')
and o.goods_title like concat('%',#{dto.keyword},'%')
and c.phone = #{dto.phone}
and o.order_status = #{dto.orderStatus}
and o.create_date between #{dto.startDate} and #{dto.endDate}
group by o.order_id order by o.order_id desc

/* ShardingSphere hint: dataSourceName=write_a */
select o.order_id as orderId,
       o.quantity as n1,
       (select count(*) from med_exam_appointment where order_id=o.order_id and status=3) as n2
from trade_order o join med_exam_appointment a on o.order_id=a.order_id
WHERE a.appointment_no = #{appointmentNo}
